(27961, 'Mark 10:50', 'Mark', 10, 50, 'نو هغه خپله چپنه یوې خواته وغورځوله، د خپل ځای څخه راپورته شو او عیسی ته راغی.', 'نو هغه خپله چپنه یوې خواته وغورجوله، د خپل جای چخه راپورته شو او عیسی ته راغی.', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27962, 'Mark 10:51', 'Mark', 10, 51, 'عیسی هغه ته وویل: «زما څخه څه غواړې چې درته ویې کړم؟» هغه ړوند سړي ځواب ورکړ: «زما استاذه، زه غواړم چې بېرته بینا شم.»', 'عیسی هغه ته وویل: «زما چخه چه غوارې چې درته ویې کرم؟» هغه روند سری جواب ورکر: «زما استاذه، زه غوارم چې بېرته بینا شم.»', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27963, 'Mark 10:52', 'Mark', 10, 52, 'عیسی هغه ته وویل: «ځه، ته خپل ایمان روغ کړې.» نو سمدلاسه هغه بینا شو او په عیسی پسې روان شو.', 'عیسی هغه ته وویل: «جه، ته خپل ایمان روغ کرې.» نو سمدلاسه هغه بینا شو او په عیسی پسې روان شو.', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27964, 'Acts 10:1', 'Acts', 10, 1, 'په قیصریه کې یو سړی ؤ چې کورنیلیوس نومېده او د رومي لښکرو د کنډک چې د «ایټالوي کنډک» په نوم یادېده، مشر ؤ.', 'په قیصریه کې یو سری و چې کورنیلیوس نومېده او د رومی لشکرو د کندک چې د «ایتالوی کندک» په نوم یادېده، مشر و.', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27965, 'Acts 10:2', 'Acts', 10, 2, 'کورنیلیوس او د هغه کورنۍ دینداره خلک وو او د خدای څخه وېرېدل. هغه به غریبو یهودیانو ته ډېر خیراتونه ورکول او تل به یې دعا کوله.', 'کورنیلیوس او د هغه کورنی دینداره خلک وو او د خدای چخه وېرېدل. هغه به غریبو یهودیانو ته دېر خیراتونه ورکول او تل به یې دعا کوله.', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27966, 'Acts 10:3', 'Acts', 10, 3, 'یوه ورځ د ماسپښین شاوخوا درې بجې هغه رویا ولیدله چې د خدای فرښته د هغه خواته راغله او ورته ویې ویل: «ای کورنیلیوسه!»', 'یوه ورج د ماسپشین شاوخوا درې بجې هغه رویا ولیدله چې د خدای فرشته د هغه خواته راغله او ورته ویې ویل: «ای کورنیلیوسه!»', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27967, 'Acts 10:4', 'Acts', 10, 4, 'هغه له وېرې په ځیر سره فرښتې ته وکتل او پوښتنه یې ترې وکړه: «ښاغلیه څه وایې؟» فرښتې ځواب ورکړ: «ستا دعاګانې او خیراتونه چې تا ورکړي وو، هغه د خدای حضور ته ورسېدل او قبول یې کړل.', 'هغه له وېرې په جیر سره فرشتې ته وکتل او پوشتنه یې ترې وکره: «شاغلیه چه وایې؟» فرشتې جواب ورکر: «ستا دعاګانې او خیراتونه چې تا ورکری وو، هغه د خدای حضور ته ورسېدل او قبول یې کرل.', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27968, 'Acts 10:5', 'Acts', 10, 5, 'اوس یو څو کسان یافا ته د شمعون پسې چې پطروس ورته ویل کیږي، ولېږه چې هغه راولي.', 'اوس یو چو کسان یافا ته د شمعون پسې چې پطروس ورته ویل کیزی، ولېزه چې هغه راولی.', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27969, 'Acts 10:6', 'Acts', 10, 6, 'هغه د شمعون څرمن جوړوونکي په کور کې چې د بحیرې په غاړه دی، مېلمه دی.»', 'هغه د شمعون چرمن جوروونکی په کور کې چې د بحیرې په غاره دی، مېلمه دی.»', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27970, 'Acts 10:7', 'Acts', 10, 7, 'کله چې هغې فرښتې د هغه سره خبرې وکړې نو لاړه، بیا کورنیلیوس خپل دوه نوکران او یو عسکر چې یو دینداره سړی ؤ او د هغه د کور د خدمتګارانو څخه ؤ، راوغوښتل.', 'کله چې هغې فرشتې د هغه سره خبرې وکرې نو لاره، بیا کورنیلیوس خپل دوه نوکران او یو عسکر چې یو دینداره سری و او د هغه د کور د خدمتګارانو چخه و، راوغوشتل.', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27971, 'Acts 10:8', 'Acts', 10, 8, 'هرڅه چې شوي وو، هغوی ته یې وویل او هغوی یې یافا ته ولېږل. پطروس رویا ویني', 'هرچه چې شوی وو، هغوی ته یې وویل او هغوی یې یافا ته ولېزل. پطروس رویا وینی', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27972, 'Acts 10:9', 'Acts', 10, 9, 'بله ورځ د غرمې په وخت کې چې هغه دوه نوکران او عسکر په لاره کې روان وو او یافا ته ورسېدل، نو په همدې وخت کې پطروس د دعا کولو دپاره پاس بام ته وخوت.', 'بله ورج د غرمې په وخت کې چې هغه دوه نوکران او عسکر په لاره کې روان وو او یافا ته ورسېدل، نو په همدې وخت کې پطروس د دعا کولو دپاره پاس بام ته وخوت.', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27973, 'Acts 10:10', 'Acts', 10, 10, 'هغه وږی شو او غوښتل یې چې څه وخوري، کله چې ډوډۍ تیارېدله، نو هغه رویا ولیدله.', 'هغه وزی شو او غوشتل یې چې چه وخوری، کله چې دودی تیارېدله، نو هغه رویا ولیدله.', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27974, 'Acts 10:11', 'Acts', 10, 11, 'هغه ولیدل چې د اسمان دروازې خلاصې شوې او د یو لوی دسترخوان په شان یو شی چې د څلورو څنډو څخه راځوړند ؤ او ښکته د ځمکې خواته راروان ؤ.', 'هغه ولیدل چې د اسمان دروازې خلاصې شوې او د یو لوی دسترخوان په شان یو شی چې د چلورو چندو چخه راجورند و او شکته د جمکې خواته راروان و.', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27975, 'Acts 10:12', 'Acts', 10, 12, 'په هغه کې هر ډول حیوانات، خزندې او مرغان وو.', 'په هغه کې هر دول حیوانات، خزندې او مرغان وو.', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27976, 'Acts 10:13', 'Acts', 10, 13, 'بیا یو اواز راغی او هغه ته یې وویل: «ای پطروسه، پاڅېږه! هغه حلال کړه او ویې خوره.»', 'بیا یو اواز راغی او هغه ته یې وویل: «ای پطروسه، پاچېزه! هغه حلال کره او ویې خوره.»', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27977, 'Acts 10:14', 'Acts', 10, 14, 'خو پطروس وویل: «څښتنه! هېڅکله نه، ما هېڅکله هم حرام او ناپاکه شی نه دی خوړلی.»', 'خو پطروس وویل: «چشتنه! هېچکله نه، ما هېچکله هم حرام او ناپاکه شی نه دی خورلی.»', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27978, 'Acts 10:15', 'Acts', 10, 15, 'په دوهم ځل بیا اواز راغی: «کوم شیان چې خدای حلال ګرځولي دي، هغه حرام مه ګڼه.»', 'په دوهم جل بیا اواز راغی: «کوم شیان چې خدای حلال ګرجولی دی، هغه حرام مه ګنه.»', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27979, 'Acts 10:16', 'Acts', 10, 16, 'درې ځلې همداسې وشول او بیا هغه دسترخوان بېرته پورته اسمان ته یووړل شو.', 'درې جلې همداسې وشول او بیا هغه دسترخوان بېرته پورته اسمان ته یوورل شو.', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27980, 'Acts 10:17', 'Acts', 10, 17, 'پطروس حیران پاتې ؤ چې د دې رویا معنی څه ده، چې په دې وخت کې هغو کسانو چې کورنیلیوس لېږلي وو، د شمعون کور پیدا کړ او هغوی د دروازې په مخکې ودرېدل.', 'پطروس حیران پاتې و چې د دې رویا معنی چه ده، چې په دې وخت کې هغو کسانو چې کورنیلیوس لېزلی وو، د شمعون کور پیدا کر او هغوی د دروازې په مخکې ودرېدل.', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27981, 'Acts 10:18', 'Acts', 10, 18, 'هغوی نارې کړې او پوښتنه یې وکړه: «ایا شمعون چې پطروس ورته هم وایي، دلته مېلمه دی؟»', 'هغوی نارې کرې او پوشتنه یې وکره: «ایا شمعون چې پطروس ورته هم وایی، دلته مېلمه دی؟»', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27982, 'Acts 10:19', 'Acts', 10, 19, 'پطروس لا د دې رویا په هکله فکر کاوه چې روح القدس ورته وویل: «ګوره، درې سړي تا لټوي.', 'پطروس لا د دې رویا په هکله فکر کاوه چې روح القدس ورته وویل: «ګوره، درې سری تا لتوی.', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27983, 'Acts 10:20', 'Acts', 10, 20, 'پاڅېږه او لاندې راښکته شه او د هغوی سره په تللو کې زړه نازړه کېږه مه، ځکه چې هغوی ما درلېږلي دي.»', 'پاچېزه او لاندې راشکته شه او د هغوی سره په تللو کې زره نازره کېزه مه، جکه چې هغوی ما درلېزلی دی.»', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27984, 'Acts 10:21', 'Acts', 10, 21, 'نو پطروس لاندې ښکته شو او هغوی ته یې وویل: «زه هماغه سړی یم چې تاسو یې لټوئ. تاسو د څه دپاره راغلي یئ؟»', 'نو پطروس لاندې شکته شو او هغوی ته یې وویل: «زه هماغه سری یم چې تاسو یې لتوی. تاسو د چه دپاره راغلی یی؟»', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27985, 'Acts 10:22', 'Acts', 10, 22, 'هغوی ځواب ورکړ: «مونږ قوماندان کورنیلیوس رالېږلي یو. هغه یو نېک او داسې سړی دی چې له خدایه وېریږي او د ټولو یهودیانو په نظر کې ډېر عزتمن سړی دی. د خدای فرښتې هغه ته ویلي وو چې تا خپل کور ته راوغواړي او څه چې وایې هغه یې واوري.»', 'هغوی جواب ورکر: «مونز قوماندان کورنیلیوس رالېزلی یو. هغه یو نېک او داسې سری دی چې له خدایه وېریزی او د تولو یهودیانو په نظر کې دېر عزتمن سری دی. د خدای فرشتې هغه ته ویلی وو چې تا خپل کور ته راوغواری او چه چې وایې هغه یې واوری.»', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27986, 'Acts 10:23', 'Acts', 10, 23, 'نو پطروس هغوی کور ته راوستل او مېلمانه یې کړل. د کورنیلیوس او پطروس لیدنه بله ورځ پطروس پاڅېده او د هغوی سره روان شو او د یافا څو ایمانداران هم ورسره ملګري وو.', 'نو پطروس هغوی کور ته راوستل او مېلمانه یې کرل. د کورنیلیوس او پطروس لیدنه بله ورج پطروس پاچېده او د هغوی سره روان شو او د یافا چو ایمانداران هم ورسره ملګری وو.', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27987, 'Acts 10:24', 'Acts', 10, 24, 'په بله ورځ هغوی قیصریې ته ورسېدل. کورنیلیوس هغوی ته په تمه ؤ او خپل خپلوان او خپل نژدې ملګري یې هم راغوښتي وو.', 'په بله ورج هغوی قیصریې ته ورسېدل. کورنیلیوس هغوی ته په تمه و او خپل خپلوان او خپل نژدې ملګری یې هم راغوشتی وو.', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27988, 'Acts 10:25', 'Acts', 10, 25, 'څنګه چې پطروس کور ته ورننوت، کورنیلیوس د هغه مخې ته ورووت او د هغه په پښو کې پرېوت او سجده یې ورته وکړه.', 'چنګه چې پطروس کور ته ورننوت، کورنیلیوس د هغه مخې ته ورووت او د هغه په پشو کې پرېوت او سجده یې ورته وکره.', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27989, 'Acts 10:26', 'Acts', 10, 26, 'خو پطروس هغه د ځمکې څخه راپورته کړ او ورته ویې ویل: «راپاڅېږه، زه هم ستا په شان یو انسان یم.»', 'خو پطروس هغه د جمکې چخه راپورته کر او ورته ویې ویل: «راپاچېزه، زه هم ستا په شان یو انسان یم.»', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27990, 'Acts 10:27', 'Acts', 10, 27, 'په داسې حال کې چې پطروس د هغه سره خبرې کولې، کور ته ننوت او ویې لیدل چې هلته ډېر خلک راټول شوي وو.', 'په داسې حال کې چې پطروس د هغه سره خبرې کولې، کور ته ننوت او ویې لیدل چې هلته دېر خلک راتول شوی وو.', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27991, 'Acts 10:28', 'Acts', 10, 28, 'پطروس هغوی ته وویل: «تاسو ته ښه معلومه ده چې د یهودیانو دپاره دا ناروا ده چې د غیریهودیانو سره ناسته ولاړه او یا ملګرتیا وکړي. خو خدای ماته دا راښودلي دي چې زه باید هېڅوک هم ناپاکه او نجس ونه ګڼم.', 'پطروس هغوی ته وویل: «تاسو ته شه معلومه ده چې د یهودیانو دپاره دا ناروا ده چې د غیریهودیانو سره ناسته ولاره او یا ملګرتیا وکری. خو خدای ماته دا راشودلی دی چې زه باید هېچوک هم ناپاکه او نجس ونه ګنم.', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27992, 'Acts 10:29', 'Acts', 10, 29, 'کله چې زه تاسو راوغوښتلم، نو پرته له کوم اعتراضه راغلم. خو اوس پوښتنه کوم چې تاسو ولې زه راوغوښتلم؟»', 'کله چې زه تاسو راوغوشتلم، نو پرته له کوم اعتراضه راغلم. خو اوس پوشتنه کوم چې تاسو ولې زه راوغوشتلم؟»', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
